SELECT first_name, last_name, salary
FROM employees
WHERE salary > 150000;

SELECT name, price, stock
FROM products
WHERE category = 'Accessories' AND stock > 100;

SELECT title, first_name, salary
FROM employees
ORDER BY title, salary DESC;

SELECT name AS product, price AS list_price, price * 0.8 AS sale_price
FROM products
WHERE category = 'Audio';

SELECT id, status FROM orders
ORDER BY CASE status WHEN 'pending' THEN 1 WHEN 'shipped' THEN 2 ELSE 3 END, id
LIMIT 6;

SELECT id, order_date,
       julianday('2024-12-31') - julianday(order_date) AS days_ago
FROM orders ORDER BY id DESC LIMIT 3;

SELECT COUNT(*) AS employees, SUM(salary) AS payroll,
       AVG(salary) AS average, MIN(salary) AS lowest, MAX(salary) AS highest
FROM employees;

SELECT COUNT(*), COUNT(email), COUNT(department_id),
       COUNT(DISTINCT department_id)
FROM employees;

SELECT e.first_name, e.title, d.name AS department
FROM employees AS e
JOIN departments AS d ON d.id = e.department_id;

SELECT s.size, c.color
FROM (SELECT 'S' AS size UNION ALL SELECT 'M') s
CROSS JOIN (SELECT 'red' AS color UNION ALL SELECT 'blue') c;

SELECT name, price, (SELECT ROUND(AVG(price), 2) FROM products) AS avg_price
FROM products
WHERE price > (SELECT AVG(price) FROM products);

SELECT COUNT(*) AS orders, ROUND(AVG(total), 2) AS avg_order_value
FROM (
    SELECT order_id, SUM(quantity * unit_price) AS total
    FROM order_items
    GROUP BY order_id
) AS order_totals;

SELECT city FROM customers
INTERSECT
SELECT location FROM departments;

SELECT id FROM customers
EXCEPT
SELECT customer_id FROM orders;

WITH RECURSIVE n(x) AS (
    SELECT 1                           -- anchor
    UNION ALL
    SELECT x + 1 FROM n WHERE x < 5    -- recursive step + stop condition
)
SELECT x FROM n;

WITH ranked AS (
    SELECT category, name, price,
           ROW_NUMBER() OVER (PARTITION BY category ORDER BY price DESC) AS rn
    FROM products
)
SELECT category, name, price FROM ranked WHERE rn = 1;

